/**
 * The editor's filmstrip: evenly spaced thumbnails tiled into ONE sprite sheet.
 *
 * One JPEG, one request, one decode in the webview — the timeline then draws
 * any thumbnail as a sub-rectangle of it. Generated by a single ffmpeg pass that
 * decodes KEYFRAMES ONLY (`-skip_frame nokey`): a filmstrip needs a picture
 * every few seconds, never every frame, and skipping the inter frames makes the
 * pass a fraction of a full decode — seconds, not minutes, on a feature-length
 * source. The cost is that a thumbnail can be up to one GOP away from its exact
 * time, which is invisible at filmstrip size; the preview player shows the
 * exact frame.
 *
 * Written through writeAtomically like every ffmpeg output: a cancelled pass
 * must never leave a truncated sprite that the cache then serves as complete.
 */
import { writeAtomically } from './atomic.js';
import { assertInputReadable, assertOutputWritable, runFfmpeg, type RunOptions } from './exec.js';

export interface FilmstripLayout {
  /** Number of thumbnails. */
  count: number;
  columns: number;
  rows: number;
  tileWidth: number;
  tileHeight: number;
  /** Media time between consecutive thumbnails (ms). */
  intervalMs: number;
}

export interface FilmstripResult extends FilmstripLayout {
  /** Absolute path of the sprite JPEG. */
  path: string;
}

const MIN_TILES = 8;
const MAX_TILES = 240;
const COLUMNS = 16;

/**
 * Choose the sprite layout for a media duration. Pure.
 *
 * About one thumbnail every two seconds, between 8 and 240 tiles: short clips
 * get a dense strip, long programmes stay one ~2.5k-px-wide JPEG. The tile is
 * 16:9 at 160 px; other aspect ratios are letterboxed inside it.
 */
export function planFilmstrip(durationMs: number, tileWidth = 160, tileHeight = 90): FilmstripLayout {
  const seconds = Math.max(0.001, durationMs / 1000);
  const count = Math.max(MIN_TILES, Math.min(MAX_TILES, Math.ceil(seconds / 2)));
  const columns = Math.min(COLUMNS, count);
  const rows = Math.ceil(count / columns);
  return { count, columns, rows, tileWidth, tileHeight, intervalMs: Math.max(1, Math.round(durationMs / count)) };
}

/** ffmpeg argv for the sprite. Pure. */
export function buildFilmstripArgs(input: string, output: string, durationMs: number, layout: FilmstripLayout): string[] {
  const seconds = Math.max(0.001, durationMs / 1000);
  const { tileWidth: w, tileHeight: h } = layout;
  const vf = [
    // `count` frames spread over the whole duration (a rational rate, so it is
    // exact for any length). eof_action=pass keeps the LAST sample: the default
    // (round) dropped it at end of stream, leaving the sprite's final tile black.
    `fps=${layout.count}/${seconds.toFixed(3)}:eof_action=pass`,
    `scale=${w}:${h}:force_original_aspect_ratio=decrease:flags=fast_bilinear`,
    `pad=${w}:${h}:(ow-iw)/2:(oh-ih)/2:color=black`,
    `tile=${layout.columns}x${layout.rows}`,
  ].join(',');
  return [
    '-hide_banner',
    '-nostdin',
    '-v',
    'error',
    // Decoder option, so it must precede -i: decode keyframes only.
    '-skip_frame',
    'nokey',
    '-i',
    input,
    '-an',
    '-sn',
    '-dn',
    '-vf',
    vf,
    '-frames:v',
    '1',
    // image2 writes ONE file (not a numbered sequence) without warning/error.
    '-update',
    '1',
    '-q:v',
    '4',
    '-y',
    output,
  ];
}

/** Render the filmstrip sprite for `input` to `output` (a .jpg path). */
export async function renderFilmstrip(
  input: string,
  output: string,
  durationMs: number,
  opts: RunOptions = {},
): Promise<FilmstripResult> {
  assertInputReadable(input);
  assertOutputWritable(output);
  const layout = planFilmstrip(durationMs);
  await writeAtomically(output, async (partial) => {
    await runFfmpeg(buildFilmstripArgs(input, partial, durationMs, layout), {
      timeoutMs: 10 * 60_000,
      ...opts,
    });
  });
  return { path: output, ...layout };
}
